package com.lolfm.composition;
import com.lolfm.champion.ChampionRoleKey;import java.util.*;
public final class TeamCompositionAnalyzer{public TeamCompositionAnalysis analyze(TeamCompositionLineup lineup,Map<ChampionRoleKey,ChampionCompositionProfile>profiles){TeamCompositionCoverage coverage=new TeamCompositionAggregator().aggregate(lineup,profiles);Map<CompositionPattern,PatternEvaluation>patterns=new CompositionPatternEvaluator().evaluate(coverage);Map<CompositionDeficiency,DeficiencyEvaluation>deficiencies=new CompositionDeficiencyEvaluator().evaluate(coverage);List<CapabilityExplanation>ce=Arrays.stream(CompositionCapability.values()).map(c->{var x=coverage.capability(c);return new CapabilityExplanation(c,x.aggregationType(),x.coverage(),x.contributors());}).toList();List<PatternExplanation>pe=Arrays.stream(CompositionPattern.values()).map(p->{var x=patterns.get(p);return new PatternExplanation(p,x.readiness(),x.componentCoverages(),x.contributorFactor(),x.primaryContributors(),x.distinctContributorRequirementSatisfied());}).toList();List<DeficiencyExplanation>de=Arrays.stream(CompositionDeficiency.values()).map(d->{var x=deficiencies.get(d);return new DeficiencyExplanation(d,x.present(),x.severity(),x.capabilityEvidence());}).toList();return new TeamCompositionAnalysis(lineup,coverage,patterns,deficiencies,new TeamCompositionExplanation(ce,pe,de));}}
